mapper.select:
/* selectEntrncPreconUnityReprts 입소현황통합보고서 - Lee SangHoon */ WITH TMP000 AS ( SELECT
T.TRPR_INFO_NO -- 대상자정보번호 , T.APLY_RCPT_SN -- 신청접수일련번호 , T5.APLY_RCPT_SRNG_SE_CD -- 신청접수심사구분코드 , T5.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD -- 신청접수심사진행상태구분코드 , T6.TRMN_SE_CD -- 종결구분코드 , T6.TRMN_CS_SE_CD -- 종결사유구분코드
, T1.SXDC_SE_CD -- 성별구분코드 , T2.ACBG_SE_CD -- 학력구분코드 , T7.ACBG_SE_CD AS SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , SUBSTR(T1.ZIP,0,2) AS ZIP -- 우편번호(시도) , T1.PBLAST_SE_CD -- 공적부조 , T1.FAM_SHAPE_SE_CD -- 가족형태구분코드 , T3.DSCSN_CONT -- 상담횟수 , T3.RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , T3.LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , T3.LGSLTN_JAIL -- 법률문제 - 소년원수감 , T3.LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , T3.LGSLTN_NONE -- 법률문제 - 해당사항없음 , T1.LIVTGT_YN -- 동거여부
FROM AFA100 T /* 신청접수 */ JOIN SEA200 T1 /* 대상자정보 */ ON T1.TRPR_INFO_NO = T.TRPR_INFO_NO JOIN AFA150 T5 /* 신청접수심사상태정보이력 */ ON T5.TRPR_INFO_NO = T.TRPR_INFO_NO AND T5.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN /* 학력상태 */ ( SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS ROW_NUMBER FROM SEA230 A JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD ) T2 ON T2.TRPR_INFO_NO = T.TRPR_INFO_NO AND T2.ROW_NUMBER = 1 LEFT JOIN /* 학업중단 */ ( SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY A.MNG_SN DESC) AS ROW_NUMBER FROM SEA240 A ) T7 ON T7.TRPR_INFO_NO = T.TRPR_INFO_NO AND T7.ROW_NUMBER = 1 LEFT JOIN /* 대상자문제상태내역 */ ( SELECT A.TRPR_INFO_NO , A.APLY_RCPT_SN , A.DSCSN_CONT , A.RPRS_MAAP_PROBM_SE_CD , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010303' THEN 1 END) AS LGSLTN_PRTCTN_OBSERV , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010304' THEN 1 END) AS LGSLTN_JAIL , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010302' THEN 1 END) AS LGSLTN_POLC_EXMN , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010301' THEN 1 END) AS LGSLTN_NONE FROM AFA120 A LEFT JOIN AFA131 B ON B.COMPNO_CHC_TYPE_MNG_NO = A.COMPNO_CHC_TYPE_MNG_NO
GROUP BY A.TRPR_INFO_NO, A.APLY_RCPT_SN, A.DSCSN_CONT, A.RPRS_MAAP_PROBM_SE_CD ) T3 ON T3.TRPR_INFO_NO = T.TRPR_INFO_NO AND T3.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN /* 사례종결 */ ( SELECT C.* , A.TRPR_INFO_NO , D.SRVC_EXCN_BIZ_NO , ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS ROW_NUMBER FROM SEB100 A JOIN SEC100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.TRMN_SRNG_RESULT_SE_CD = '02' JOIN SEC100 C ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND C.TRMN_SRNG_RESULT_SE_CD = '01' JOIN SEB120 D ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND D.DEL_YN != 'Y' ) T6 ON T6.ROW_NUMBER = 1 AND T6.TRPR_INFO_NO = T.TRPR_INFO_NO AND T6.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO JOIN SDA420 T8 /* 서비스실행사업 */ ON T8.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO JOIN SDA400 T9 /* 서비스사업 */ ON T9.SRVC_BIZ_NO = T8.SRVC_BIZ_NO
WHERE 1=1
AND T9.BIZ_YR IN
#{arr}
AND T.RSFR_INST_NO IN
#{arr}
AND T.SRVC_EXCN_BIZ_NO IN
#{arr}
)
SELECT SE -- 구분 , COUNT(CASE WHEN SXDC_SE_CD = 'M' THEN 1 END) AS SXDC_MALE_NMPR -- 성별-남-인원 , COUNT(CASE WHEN SXDC_SE_CD = 'F' THEN 1 END) AS SXDC_FEMALE_NMPR -- 성별-여-인원 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_MALE -- 교급-초등-남 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND SCHULW_DSCNTC_ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_MALE_SCHULW_DSCNTC -- 교급-초등-남(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_FEMALE -- 교급-초등-여 , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND SCHULW_DSCNTC_ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_FEMALE_SCHULW_DSCNTC -- 교급-초등-여(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_MALE -- 교급-중등-남 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND SCHULW_DSCNTC_ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_MALE_SCHULW_DSCNTC -- 교급-중등-남(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_FEMALE -- 교급-중등-여 , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND SCHULW_DSCNTC_ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_FEMALE_SCHULW_DSCNTC -- 교급-중등-여(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_MALE -- 교급-고등-남 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND SCHULW_DSCNTC_ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_MALE_SCHULW_DSCNTC -- 교급-고등-남(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_FEMALE -- 교급-고등-여 , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND SCHULW_DSCNTC_ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_FEMALE_SCHULW_DSCNTC -- 교급-고등-여(학업중단) , COUNT(CASE WHEN ZIP BETWEEN '01' AND '09' THEN 1 END) AS RGN_SEOUL -- 지역-서울 , COUNT(CASE WHEN ZIP BETWEEN '46' AND '49' THEN 1 END) AS RGN_BUSAN -- 지역-부산 , COUNT(CASE WHEN ZIP BETWEEN '41' AND '43' THEN 1 END) AS RGN_DAEGU -- 지역-대구 , COUNT(CASE WHEN ZIP BETWEEN '21' AND '23' THEN 1 END) AS RGN_INCHEON -- 지역-인천 , COUNT(CASE WHEN ZIP BETWEEN '61' AND '62' THEN 1 END) AS RGN_GWANGJU -- 지역-광주 , COUNT(CASE WHEN ZIP BETWEEN '34' AND '35' THEN 1 END) AS RGN_DAEJEON -- 지역-대전 , COUNT(CASE WHEN ZIP BETWEEN '44' AND '45' THEN 1 END) AS RGN_ULSAN -- 지역-울산 , COUNT(CASE WHEN ZIP BETWEEN '30' AND '30' THEN 1 END) AS RGN_SEJONG -- 지역-세종 , COUNT(CASE WHEN ZIP BETWEEN '63' AND '63' THEN 1 END) AS RGN_JEJU -- 지역-제주 , COUNT(CASE WHEN ZIP BETWEEN '10' AND '20' THEN 1 END) AS RGN_GYEONGGI -- 지역-경기 , COUNT(CASE WHEN ZIP BETWEEN '24' AND '26' THEN 1 END) AS RGN_GANGWON -- 지역-강원 , COUNT(CASE WHEN ZIP BETWEEN '27' AND '29' THEN 1 END) AS RGN_CHUNGBUK -- 지역-충북 , COUNT(CASE WHEN ZIP BETWEEN '31' AND '33' THEN 1 END) AS RGN_CHUNGNAM -- 지역-충남 , COUNT(CASE WHEN ZIP BETWEEN '54' AND '56' THEN 1 END) AS RGN_JEONBUK -- 지역-전북 , COUNT(CASE WHEN ZIP BETWEEN '57' AND '60' THEN 1 END) AS RGN_JEONNAM -- 지역-전남 , COUNT(CASE WHEN ZIP BETWEEN '36' AND '40' THEN 1 END) AS RGN_GYEONGBUK -- 지역-경북 , COUNT(CASE WHEN ZIP BETWEEN '50' AND '53' THEN 1 END) AS RGN_GYEONGNAM -- 지역-경남 , COUNT(CASE WHEN PBLAST_SE_CD = '01' THEN 1 END) AS PBLAST_BSIS_LVING_RECIPI -- 공적부조-국민기초생활수급대상 , COUNT(CASE WHEN PBLAST_SE_CD = '02' THEN 1 END) AS PBLAST_LWRFMY -- 공적부조-차상위계층 , COUNT(CASE WHEN PBLAST_SE_CD = '03' THEN 1 END) AS PBLAST_SGLPR -- 공적부조-저소득한부모가족 , COUNT(CASE WHEN PBLAST_SE_CD = '04' THEN 1 END) AS PBLAST_NORLVT -- 공적부조-미해당 , COUNT(CASE WHEN PBLAST_SE_CD = '05' THEN 1 END) AS PBLAST_UNCNFR -- 공적부조-미확인 , COUNT(CASE WHEN PBLAST_SE_CD = '99' THEN 1 END) AS PBLAST_ETC -- 공적부조-기타 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '01' THEN 1 END) AS FAM_SHAPE_PARNTS -- 가족형태-부모동거 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '02' THEN 1 END) AS FAM_SHAPE_SGLE -- 가족형태-혼자거주 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '03' THEN 1 END) AS FAM_SHAPE_BRTHRS -- 가족형태-형제동거 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '04' THEN 1 END) AS FAM_SHAPE_RELATIVE -- 거족형태-친척동거 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '05' THEN 1 END) AS FAM_SHAPE_SGLPR -- 거족형태-한부모가족 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '06' THEN 1 END) AS FAM_SHAPE_GRND_PARNTS -- 가족형태-조손가족 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '07' THEN 1 END) AS FAM_SHAPE_FCLTY -- 가족형태-시설보호 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '08' THEN 1 END) AS FAM_SHAPE_CNSGN -- 가족형태-가정위탁 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '09' THEN 1 END) AS FAM_SHAPE_UNCNFR -- 가족형태-미확인 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '99' THEN 1 END) AS FAM_SHAPE_ETC -- 가족형태-기타 , COUNT(CASE WHEN DSCSN_CONT > 0 THEN 1 END) AS DSCSN_MDLRT_YN_Y_NOPE -- 상담치료경험여부-있음-인원 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '17' THEN 1 END) AS MAAP_GAME -- 주호소-게임 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '18' THEN 1 END) AS MAAP_INDV_MEDIAA -- 주호소-개인미디어 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '19' THEN 1 END) AS MAAP_SNS_CHTT -- 주호소-SNS및채팅 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '20' THEN 1 END) AS MAAP_GAMBLE -- 주호소-도박및사기 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '21' THEN 1 END) AS MAAP_ADULT -- 주호소-성인물시청 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '99' THEN 1 END) AS MAAP_ETC -- 주호소-기타 , COUNT(CASE WHEN LGSLTN_PRTCTN_OBSERV = 1 THEN 1 END) AS LGSLTN_PRTCTN_OBSERV -- 법률문제-보호관찰 , COUNT(CASE WHEN LGSLTN_JAIL = 1 THEN 1 END) AS LGSLTN_JAIL -- 법률문제-소년원수감 , COUNT(CASE WHEN LGSLTN_POLC_EXMN = 1 THEN 1 END) AS LGSLTN_POLC_EXMN -- 법률문제-경찰조사 , COUNT(CASE WHEN LGSLTN_NONE = 1 THEN 1 END) AS LGSLTN_NONE -- 법률문제-해당사항없음 , COUNT(CASE WHEN LIVTGT_YN = 'Y' THEN 1 END) AS LIVTGT_YN_Y -- 동거여부-예 , COUNT(CASE WHEN LIVTGT_YN = 'N' THEN 1 END) AS LIVTGT_YN_N -- 동거여부-아니요 , COUNT(TRPR_INFO_NO) AS NOPE_SUM -- 인원수합계
FROM ( /* 더미 */ SELECT NULL AS SE -- 구분 , NULL AS OD -- 순서 , NULL AS TRPR_INFO_NO -- 대상자정보번호 , NULL AS APLY_RCPT_SN -- 신청접수일련번호 , NULL AS SXDC_SE_CD -- 성별구분코드 , NULL AS ACBG_SE_CD -- 학력구분코드 , NULL AS SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , NULL AS ZIP -- 우편번호(시도) , NULL AS PBLAST_SE_CD -- 공적부조 , NULL AS FAM_SHAPE_SE_CD -- 가족형태구분코드 , NULL AS DSCSN_CONT -- 상담횟수 , NULL AS RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , NULL AS LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , NULL AS LGSLTN_JAIL -- 법률문제 - 소년원수감 , NULL AS LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , NULL AS LGSLTN_NONE -- 법률문제 - 해당사항없음 , NULL AS LIVTGT_YN -- 동거여부 FROM DUAL WHERE 1=2
/* 서류심사-서류선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 , SXDC_SE_CD -- 성별구분코드 , ACBG_SE_CD -- 학력구분코드 , SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , ZIP -- 우편번호(시도) , PBLAST_SE_CD -- 공적부조 , FAM_SHAPE_SE_CD -- 가족형태구분코드 , DSCSN_CONT -- 상담횟수 , RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , LGSLTN_JAIL -- 법률문제 - 소년원수감 , LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , LGSLTN_NONE -- 법률문제 - 해당사항없음 , LIVTGT_YN -- 동거여부 FROM ( SELECT '서류심사-서류선정' AS SE , 11 AS OD FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0401')
/* 서류심사-서류미선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 , SXDC_SE_CD -- 성별구분코드 , ACBG_SE_CD -- 학력구분코드 , SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , ZIP -- 우편번호(시도) , PBLAST_SE_CD -- 공적부조 , FAM_SHAPE_SE_CD -- 가족형태구분코드 , DSCSN_CONT -- 상담횟수 , RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , LGSLTN_JAIL -- 법률문제 - 소년원수감 , LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , LGSLTN_NONE -- 법률문제 - 해당사항없음 , LIVTGT_YN -- 동거여부 FROM ( SELECT '서류심사-서류미선정' AS SE , 12 AS OD FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0402')
/* 서류심사-반송 */ UNION ALL
SELECT DISTINCT SE -- 구분 , OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 , SXDC_SE_CD -- 성별구분코드 , ACBG_SE_CD -- 학력구분코드 , SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , ZIP -- 우편번호(시도) , PBLAST_SE_CD -- 공적부조 , FAM_SHAPE_SE_CD -- 가족형태구분코드 , DSCSN_CONT -- 상담횟수 , RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , LGSLTN_JAIL -- 법률문제 - 소년원수감 , LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , LGSLTN_NONE -- 법률문제 - 해당사항없음 , LIVTGT_YN -- 동거여부 FROM ( SELECT '서류심사-반송' AS SE , 14 AS OD FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0403')
/* 면접심사-선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 , SXDC_SE_CD -- 성별구분코드 , ACBG_SE_CD -- 학력구분코드 , SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , ZIP -- 우편번호(시도) , PBLAST_SE_CD -- 공적부조 , FAM_SHAPE_SE_CD -- 가족형태구분코드 , DSCSN_CONT -- 상담횟수 , RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , LGSLTN_JAIL -- 법률문제 - 소년원수감 , LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , LGSLTN_NONE -- 법률문제 - 해당사항없음 , LIVTGT_YN -- 동거여부 FROM ( SELECT '면접심사-선정' AS SE , 21 AS OD FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0504')
